"use strict";(self.webpackChunkml_seminars=self.webpackChunkml_seminars||[]).push([[758],{23:function(n){n.exports='<!DOCTYPE html>\n<html xmlns="http://www.w3.org/1999/xhtml" lang xml:lang>\n<head>\n  <meta charset="utf-8" />\n  <meta name="generator" content="pandoc" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=yes" />\n  <title>lab-07-model-selection</title>\n  <style>\nhtml {\ncolor: #1a1a1a;\nbackground-color: #fdfdfd;\n}\nbody {\nmargin: 0 auto;\nmax-width: 36em;\npadding-left: 50px;\npadding-right: 50px;\npadding-top: 50px;\npadding-bottom: 50px;\nhyphens: auto;\noverflow-wrap: break-word;\ntext-rendering: optimizeLegibility;\nfont-kerning: normal;\n}\n@media (max-width: 600px) {\nbody {\nfont-size: 0.9em;\npadding: 12px;\n}\nh1 {\nfont-size: 1.8em;\n}\n}\n@media print {\nhtml {\nbackground-color: white;\n}\nbody {\nbackground-color: transparent;\ncolor: black;\nfont-size: 12pt;\n}\np, h2, h3 {\norphans: 3;\nwidows: 3;\n}\nh2, h3, h4 {\npage-break-after: avoid;\n}\n}\np {\nmargin: 1em 0;\n}\na {\ncolor: #1a1a1a;\n}\na:visited {\ncolor: #1a1a1a;\n}\nimg {\nmax-width: 100%;\n}\nsvg {\nheight: auto;\nmax-width: 100%;\n}\nh1, h2, h3, h4, h5, h6 {\nmargin-top: 1.4em;\n}\nh5, h6 {\nfont-size: 1em;\nfont-style: italic;\n}\nh6 {\nfont-weight: normal;\n}\nol, ul {\npadding-left: 1.7em;\nmargin-top: 1em;\n}\nli > ol, li > ul {\nmargin-top: 0;\n}\nblockquote {\nmargin: 1em 0 1em 1.7em;\npadding-left: 1em;\nborder-left: 2px solid #e6e6e6;\ncolor: #606060;\n}\ncode {\nfont-family: Menlo, Monaco, Consolas, \'Lucida Console\', monospace;\nfont-size: 85%;\nmargin: 0;\nhyphens: manual;\n}\npre {\nmargin: 1em 0;\noverflow: auto;\n}\npre code {\npadding: 0;\noverflow: visible;\noverflow-wrap: normal;\n}\n.sourceCode {\nbackground-color: transparent;\noverflow: visible;\n}\nhr {\nborder: none;\nborder-top: 1px solid #1a1a1a;\nheight: 1px;\nmargin: 1em 0;\n}\ntable {\nmargin: 1em 0;\nborder-collapse: collapse;\nwidth: 100%;\noverflow-x: auto;\ndisplay: block;\nfont-variant-numeric: lining-nums tabular-nums;\n}\ntable caption {\nmargin-bottom: 0.75em;\n}\ntbody {\nmargin-top: 0.5em;\nborder-top: 1px solid #1a1a1a;\nborder-bottom: 1px solid #1a1a1a;\n}\nth {\nborder-top: 1px solid #1a1a1a;\npadding: 0.25em 0.5em 0.25em 0.5em;\n}\ntd {\npadding: 0.125em 0.5em 0.25em 0.5em;\n}\nheader {\nmargin-bottom: 4em;\ntext-align: center;\n}\n#TOC li {\nlist-style: none;\n}\n#TOC ul {\npadding-left: 1.3em;\n}\n#TOC > ul {\npadding-left: 0;\n}\n#TOC a:not(:hover) {\ntext-decoration: none;\n}\ncode{white-space: pre-wrap;}\nspan.smallcaps{font-variant: small-caps;}\ndiv.columns{display: flex; gap: min(4vw, 1.5em);}\ndiv.column{flex: auto; overflow-x: auto;}\ndiv.hanging-indent{margin-left: 1.5em; text-indent: -1.5em;}\n\nul.task-list[class]{list-style: none;}\nul.task-list li input[type="checkbox"] {\nfont-size: inherit;\nwidth: 0.8em;\nmargin: 0 0.8em 0.2em -1.6em;\nvertical-align: middle;\n}\n\nhtml { -webkit-text-size-adjust: 100%; }\npre > code.sourceCode { white-space: pre; position: relative; }\npre > code.sourceCode > span { display: inline-block; line-height: 1.25; }\npre > code.sourceCode > span:empty { height: 1.2em; }\n.sourceCode { overflow: visible; }\ncode.sourceCode > span { color: inherit; text-decoration: inherit; }\ndiv.sourceCode { margin: 1em 0; }\npre.sourceCode { margin: 0; }\n@media screen {\ndiv.sourceCode { overflow: auto; }\n}\n@media print {\npre > code.sourceCode { white-space: pre-wrap; }\npre > code.sourceCode > span { text-indent: -5em; padding-left: 5em; }\n}\npre.numberSource code\n{ counter-reset: source-line 0; }\npre.numberSource code > span\n{ position: relative; left: -4em; counter-increment: source-line; }\npre.numberSource code > span > a:first-child::before\n{ content: counter(source-line);\nposition: relative; left: -1em; text-align: right; vertical-align: baseline;\nborder: none; display: inline-block;\n-webkit-touch-callout: none; -webkit-user-select: none;\n-khtml-user-select: none; -moz-user-select: none;\n-ms-user-select: none; user-select: none;\npadding: 0 4px; width: 4em;\ncolor: #aaaaaa;\n}\npre.numberSource { margin-left: 3em; border-left: 1px solid #aaaaaa; padding-left: 4px; }\ndiv.sourceCode\n{ background-color: #f8f8f8; }\n@media screen {\npre > code.sourceCode > span > a:first-child::before { text-decoration: underline; }\n}\ncode span.al { color: #ef2929; } \ncode span.an { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.at { color: #204a87; } \ncode span.bn { color: #0000cf; } \ncode span.cf { color: #204a87; font-weight: bold; } \ncode span.ch { color: #4e9a06; } \ncode span.cn { color: #8f5902; } \ncode span.co { color: #8f5902; font-style: italic; } \ncode span.cv { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.do { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.dt { color: #204a87; } \ncode span.dv { color: #0000cf; } \ncode span.er { color: #a40000; font-weight: bold; } \ncode span.ex { } \ncode span.fl { color: #0000cf; } \ncode span.fu { color: #204a87; font-weight: bold; } \ncode span.im { } \ncode span.in { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.kw { color: #204a87; font-weight: bold; } \ncode span.op { color: #ce5c00; font-weight: bold; } \ncode span.ot { color: #8f5902; } \ncode span.pp { color: #8f5902; font-style: italic; } \ncode span.sc { color: #ce5c00; font-weight: bold; } \ncode span.ss { color: #4e9a06; } \ncode span.st { color: #4e9a06; } \ncode span.va { color: #000000; } \ncode span.vs { color: #4e9a06; } \ncode span.wa { color: #8f5902; font-weight: bold; font-style: italic; } \n</style>\n</head>\n<body>\n<div id="ed82b5f3" class="cell markdown">\n<h1 id="лабораторная-работа--7-выбор-модели-кросс-валидация-и-интерпретация">Лабораторная\nработа № 7. Выбор модели, кросс-валидация и интерпретация</h1>\n<p><strong>Курс:</strong> Классическое машинное обучение, 4 курс\nприкладной математики</p>\n<h2 id="цель-работы">Цель работы</h2>\n<p>Освоить методы кросс-валидации, GridSearch, построение пайплайнов и\nинтерпретацию моделей.</p>\n<p><strong>Используемые инструменты:</strong>\n<code>sklearn.pipeline</code>, <code>sklearn.model_selection</code>,\n<code>shap</code>, <code>matplotlib</code>.</p>\n</div>\n<div id="00a7431f" class="cell markdown">\n<h3 id="регламент-сдачи">Регламент сдачи</h3>\n<p>Работа сдаётся в виде этого же ноутбука, дополненного вашим кодом.\nОбязательно:</p>\n<ol>\n<li>Читаемый код с комментариями.</li>\n<li>Визуализации (графики, таблицы).</li>\n<li><strong>Текстовый вывод после каждого задания</strong> — не только\nкод, но и объяснение результата.</li>\n<li>Финальный вывод по работе.</li>\n</ol>\n<p><strong>Критерии оценки:</strong> корректность реализации — 30 %,\nкачество визуализаций и анализа — 20 %, обоснованность выводов — 20 %,\nсравнение с эталонными реализациями — 15 %, оригинальность и\nдополнительная работа — 15 %.</p>\n<blockquote>\n<p>Ячейки, помеченные <code># TODO</code>, нужно заполнить\nсамостоятельно. Ячейки с готовым кодом можно просто выполнить — они\nподготавливают данные и графики.</p>\n</blockquote>\n</div>\n<div id="0015b8b5" class="cell markdown">\n<h2 id="подготовка-окружения">Подготовка окружения</h2>\n</div>\n<div id="02e5ea2a" class="cell code">\n<div class="sourceCode" id="cb1"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb1-1"><a href="#cb1-1" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> numpy <span class="im">as</span> np</span>\n<span id="cb1-2"><a href="#cb1-2" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> pandas <span class="im">as</span> pd</span>\n<span id="cb1-3"><a href="#cb1-3" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> matplotlib.pyplot <span class="im">as</span> plt</span>\n<span id="cb1-4"><a href="#cb1-4" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> seaborn <span class="im">as</span> sns</span>\n<span id="cb1-5"><a href="#cb1-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-6"><a href="#cb1-6" aria-hidden="true" tabindex="-1"></a><span class="op">%</span>matplotlib inline</span>\n<span id="cb1-7"><a href="#cb1-7" aria-hidden="true" tabindex="-1"></a>plt.rcParams.update({</span>\n<span id="cb1-8"><a href="#cb1-8" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.figsize&quot;</span>: (<span class="dv">7</span>, <span class="dv">4</span>),</span>\n<span id="cb1-9"><a href="#cb1-9" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.dpi&quot;</span>: <span class="dv">110</span>,</span>\n<span id="cb1-10"><a href="#cb1-10" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.grid&quot;</span>: <span class="va">True</span>,</span>\n<span id="cb1-11"><a href="#cb1-11" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;grid.alpha&quot;</span>: <span class="fl">0.25</span>,</span>\n<span id="cb1-12"><a href="#cb1-12" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;font.size&quot;</span>: <span class="dv">11</span>,</span>\n<span id="cb1-13"><a href="#cb1-13" aria-hidden="true" tabindex="-1"></a>})</span>\n<span id="cb1-14"><a href="#cb1-14" aria-hidden="true" tabindex="-1"></a>sns.set_palette(<span class="st">&quot;viridis&quot;</span>)</span>\n<span id="cb1-15"><a href="#cb1-15" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-16"><a href="#cb1-16" aria-hidden="true" tabindex="-1"></a>RANDOM_STATE <span class="op">=</span> <span class="dv">42</span></span>\n<span id="cb1-17"><a href="#cb1-17" aria-hidden="true" tabindex="-1"></a>rng <span class="op">=</span> np.random.default_rng(RANDOM_STATE)</span>\n<span id="cb1-18"><a href="#cb1-18" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-19"><a href="#cb1-19" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.datasets <span class="im">import</span> load_breast_cancer</span>\n<span id="cb1-20"><a href="#cb1-20" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.model_selection <span class="im">import</span> train_test_split</span>\n<span id="cb1-21"><a href="#cb1-21" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-22"><a href="#cb1-22" aria-hidden="true" tabindex="-1"></a>data <span class="op">=</span> load_breast_cancer()</span>\n<span id="cb1-23"><a href="#cb1-23" aria-hidden="true" tabindex="-1"></a>X_train, X_test, y_train, y_test <span class="op">=</span> train_test_split(</span>\n<span id="cb1-24"><a href="#cb1-24" aria-hidden="true" tabindex="-1"></a>    data.data, data.target, test_size<span class="op">=</span><span class="fl">0.3</span>, stratify<span class="op">=</span>data.target, random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb1-25"><a href="#cb1-25" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-26"><a href="#cb1-26" aria-hidden="true" tabindex="-1"></a>feature_names <span class="op">=</span> data.feature_names</span>\n<span id="cb1-27"><a href="#cb1-27" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;train:&quot;</span>, X_train.shape)</span></code></pre></div>\n</div>\n<div id="932f996a" class="cell markdown">\n<h2 id="задание-1-пайплайн">Задание 1. Пайплайн</h2>\n<p>Соберите цепочку</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext mathvariant="normal">StandardScaler</mtext><mo>→</mo><mtext mathvariant="normal">PCA</mtext><mo stretchy="false" form="prefix">(</mo><mi>n</mi><mi>_</mi><mi>c</mi><mi>o</mi><mi>m</mi><mi>p</mi><mi>o</mi><mi>n</mi><mi>e</mi><mi>n</mi><mi>t</mi><mi>s</mi><mo>=</mo><mn>10</mn><mo stretchy="false" form="postfix">)</mo><mo>→</mo><mtext mathvariant="normal">SVC</mtext><mo stretchy="false" form="prefix">(</mo><mi>k</mi><mi>e</mi><mi>r</mi><mi>n</mi><mi>e</mi><mi>l</mi><msup><mo>=</mo><mo>′</mo></msup><mi>r</mi><mi>b</mi><msup><mi>f</mi><mo>′</mo></msup><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\text{StandardScaler} \\rightarrow \\text{PCA}(n\\_components=10) \\rightarrow \\text{SVC}(kernel=&#39;rbf&#39;)</annotation></semantics></math></p>\n<p><strong>Зачем пайплайн?</strong> При кросс-валидации масштабирование\nи PCA должны обучаться <strong>только на обучающих фолдах</strong>. Если\nсделать <code>scaler.fit(X)</code> до разбиения, информация о тестовых\nобъектах просочится в модель, и оценка качества будет завышенной.</p>\n</div>\n<div id="799bf858" class="cell code">\n<div class="sourceCode" id="cb2"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb2-1"><a href="#cb2-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.pipeline <span class="im">import</span> Pipeline</span>\n<span id="cb2-2"><a href="#cb2-2" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.preprocessing <span class="im">import</span> StandardScaler</span>\n<span id="cb2-3"><a href="#cb2-3" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.decomposition <span class="im">import</span> PCA</span>\n<span id="cb2-4"><a href="#cb2-4" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.svm <span class="im">import</span> SVC</span>\n<span id="cb2-5"><a href="#cb2-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-6"><a href="#cb2-6" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: соберите Pipeline из трёх шагов и обучите его как обычную модель</span></span></code></pre></div>\n</div>\n<div id="14a539b4" class="cell markdown">\n<h2 id="задание-2-gridsearchcv">Задание 2. GridSearchCV</h2>\n<p>Переберите сетку:</p>\n<ul>\n<li><math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>C</mi><mo>∈</mo><mo stretchy="false" form="prefix">{</mo><mn>0.1</mn><mo>,</mo><mspace width="0.222em"></mspace><mn>1</mn><mo>,</mo><mspace width="0.222em"></mspace><mn>10</mn><mo>,</mo><mspace width="0.222em"></mspace><mn>100</mn><mo stretchy="false" form="postfix">}</mo></mrow><annotation encoding="application/x-tex">C \\in \\{0.1,\\ 1,\\ 10,\\ 100\\}</annotation></semantics></math>,</li>\n<li><math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>γ</mi><mo>∈</mo><mo stretchy="false" form="prefix">{</mo><mn>0.01</mn><mo>,</mo><mspace width="0.222em"></mspace><mn>0.1</mn><mo>,</mo><mspace width="0.222em"></mspace><mn>1</mn><mo>,</mo><mspace width="0.222em"></mspace><mn>10</mn><mo stretchy="false" form="postfix">}</mo></mrow><annotation encoding="application/x-tex">\\gamma \\in \\{0.01,\\ 0.1,\\ 1,\\ 10\\}</annotation></semantics></math>,</li>\n<li>число компонент PCA\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>k</mi><mo>∈</mo><mo stretchy="false" form="prefix">{</mo><mn>5</mn><mo>,</mo><mspace width="0.222em"></mspace><mn>10</mn><mo>,</mo><mspace width="0.222em"></mspace><mn>15</mn><mo>,</mo><mspace width="0.222em"></mspace><mn>20</mn><mo stretchy="false" form="postfix">}</mo></mrow><annotation encoding="application/x-tex">k \\in \\{5,\\ 10,\\ 15,\\ 20\\}</annotation></semantics></math>.</li>\n</ul>\n<p>Обратите внимание на синтаксис имён параметров:\n<code>имя_шага__параметр</code>, например <code>svc__C</code>.</p>\n</div>\n<div id="7d120dbe" class="cell code">\n<div class="sourceCode" id="cb3"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb3-1"><a href="#cb3-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.model_selection <span class="im">import</span> GridSearchCV</span>\n<span id="cb3-2"><a href="#cb3-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-3"><a href="#cb3-3" aria-hidden="true" tabindex="-1"></a>param_grid <span class="op">=</span> {</span>\n<span id="cb3-4"><a href="#cb3-4" aria-hidden="true" tabindex="-1"></a>    <span class="co"># </span><span class="al">TODO</span><span class="co">: заполните сетку</span></span>\n<span id="cb3-5"><a href="#cb3-5" aria-hidden="true" tabindex="-1"></a>}</span>\n<span id="cb3-6"><a href="#cb3-6" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-7"><a href="#cb3-7" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: GridSearchCV(pipe, param_grid, cv=5, scoring=&quot;roc_auc&quot;, n_jobs=-1)</span></span>\n<span id="cb3-8"><a href="#cb3-8" aria-hidden="true" tabindex="-1"></a><span class="co">#       Выведите best_params_ и best_score_. Сколько всего обучений выполнилось?</span></span></code></pre></div>\n</div>\n<div id="f773e35b" class="cell markdown">\n<h2 id="задание-3-gridsearch-против-randomizedsearch">Задание 3.\nGridSearch против RandomizedSearch</h2>\n<p>Запустите <code>RandomizedSearchCV</code> с 20 итерациями по той же\n(или более широкой непрерывной) сетке. Сравните по времени работы и по\nкачеству.</p>\n</div>\n<div id="6cdf6acd" class="cell code">\n<div class="sourceCode" id="cb4"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb4-1"><a href="#cb4-1" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> time</span>\n<span id="cb4-2"><a href="#cb4-2" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.model_selection <span class="im">import</span> RandomizedSearchCV</span>\n<span id="cb4-3"><a href="#cb4-3" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> scipy.stats <span class="im">import</span> loguniform</span>\n<span id="cb4-4"><a href="#cb4-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-5"><a href="#cb4-5" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: замерьте время обоих поисков через time.perf_counter(),</span></span>\n<span id="cb4-6"><a href="#cb4-6" aria-hidden="true" tabindex="-1"></a><span class="co">#       сравните best_score_ и число обученных моделей.</span></span>\n<span id="cb4-7"><a href="#cb4-7" aria-hidden="true" tabindex="-1"></a><span class="co">#       Сделайте вывод: когда случайный поиск предпочтительнее полного перебора?</span></span></code></pre></div>\n</div>\n<div id="67f33f1d" class="cell markdown">\n<h2 id="задание-4-финальная-модель">Задание 4. Финальная модель</h2>\n<p>Обучите лучшую модель на <strong>всей</strong> обучающей выборке и\nоцените один раз на тестовой.</p>\n</div>\n<div id="f6036b11" class="cell code">\n<div class="sourceCode" id="cb5"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb5-1"><a href="#cb5-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.metrics <span class="im">import</span> roc_auc_score, classification_report, RocCurveDisplay</span>\n<span id="cb5-2"><a href="#cb5-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-3"><a href="#cb5-3" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: оцените финальную модель. Сравните оценку на кросс-валидации с оценкой на тесте —</span></span>\n<span id="cb5-4"><a href="#cb5-4" aria-hidden="true" tabindex="-1"></a><span class="co">#       насколько они близки? Если CV-оценка заметно выше, что это значит?</span></span></code></pre></div>\n</div>\n<div id="63a7b0b2" class="cell markdown">\n<h2 id="задание-5-интерпретация-через-shap">Задание 5. Интерпретация\nчерез SHAP</h2>\n<p>SHAP приписывает каждому признаку вклад в конкретное предсказание,\nопираясь на значения Шепли из теории кооперативных игр: вклад признака\nусредняется по всем возможным «коалициям» признаков.</p>\n<blockquote>\n<p>Если <code>shap</code> и <code>xgboost</code> не установлены:\n<code>pip install shap xgboost</code>. Как запасной вариант —\n<code>sklearn.inspection.permutation_importance</code> и\n<code>PartialDependenceDisplay</code>.</p>\n</blockquote>\n</div>\n<div id="c2c80aee" class="cell code">\n<div class="sourceCode" id="cb6"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb6-1"><a href="#cb6-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: обучите XGBClassifier (или GradientBoostingClassifier) на тех же данных</span></span></code></pre></div>\n</div>\n<div id="00cc6254" class="cell code">\n<div class="sourceCode" id="cb7"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb7-1"><a href="#cb7-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: explainer = shap.TreeExplainer(model); shap_values = explainer(X_test)</span></span>\n<span id="cb7-2"><a href="#cb7-2" aria-hidden="true" tabindex="-1"></a><span class="co">#       Постройте:</span></span>\n<span id="cb7-3"><a href="#cb7-3" aria-hidden="true" tabindex="-1"></a><span class="co">#         - shap.summary_plot(shap_values, X_test, feature_names=feature_names)</span></span>\n<span id="cb7-4"><a href="#cb7-4" aria-hidden="true" tabindex="-1"></a><span class="co">#         - shap.plots.waterfall(shap_values[0])  — разбор одного объекта</span></span>\n<span id="cb7-5"><a href="#cb7-5" aria-hidden="true" tabindex="-1"></a><span class="co">#       Какие 5 признаков влияют сильнее всего? Совпадают ли они с feature_importances_?</span></span></code></pre></div>\n</div>\n<div id="e5488c01" class="cell markdown">\n<p><strong>Вывод:</strong> <em>чем SHAP-важность отличается от\n<code>feature_importances_</code> дерева? Почему первая может быть\nнадёжнее?</em></p>\n</div>\n<div id="3420a842" class="cell markdown">\n<h2 id="дополнительное-задание-вложенная-кросс-валидация">Дополнительное\nзадание. Вложенная кросс-валидация</h2>\n<p>Обычная схема «подобрали гиперпараметры по CV → взяли best_score_ как\nоценку качества» даёт <strong>смещённую вверх</strong> оценку:\nгиперпараметры подогнаны под те же фолды.</p>\n<p>Nested CV разделяет задачи: внешний цикл оценивает качество,\nвнутренний — подбирает параметры.</p>\n<div class="sourceCode" id="cb8"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb8-1"><a href="#cb8-1" aria-hidden="true" tabindex="-1"></a>inner <span class="op">=</span> KFold(n_splits<span class="op">=</span><span class="dv">3</span>, shuffle<span class="op">=</span><span class="va">True</span>, random_state<span class="op">=</span><span class="dv">0</span>)</span>\n<span id="cb8-2"><a href="#cb8-2" aria-hidden="true" tabindex="-1"></a>outer <span class="op">=</span> KFold(n_splits<span class="op">=</span><span class="dv">5</span>, shuffle<span class="op">=</span><span class="va">True</span>, random_state<span class="op">=</span><span class="dv">0</span>)</span>\n<span id="cb8-3"><a href="#cb8-3" aria-hidden="true" tabindex="-1"></a>clf <span class="op">=</span> GridSearchCV(pipe, param_grid, cv<span class="op">=</span>inner, scoring<span class="op">=</span><span class="st">&quot;roc_auc&quot;</span>)</span>\n<span id="cb8-4"><a href="#cb8-4" aria-hidden="true" tabindex="-1"></a>scores <span class="op">=</span> cross_val_score(clf, X, y, cv<span class="op">=</span>outer, scoring<span class="op">=</span><span class="st">&quot;roc_auc&quot;</span>)</span></code></pre></div>\n</div>\n<div id="97bfb551" class="cell code">\n<div class="sourceCode" id="cb9"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb9-1"><a href="#cb9-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: реализуйте вложенную кросс-валидацию и сравните её оценку</span></span>\n<span id="cb9-2"><a href="#cb9-2" aria-hidden="true" tabindex="-1"></a><span class="co">#       с best_score_ из обычного GridSearchCV. Насколько велико смещение?</span></span></code></pre></div>\n</div>\n<div id="f897b671" class="cell markdown">\n<h2 id="финальный-вывод">Финальный вывод</h2>\n<p><em>Напишите здесь связный вывод по работе (5–10\nпредложений):</em></p>\n<ul>\n<li>какие методы вы применили и почему;</li>\n<li>какие результаты получили в числах;</li>\n<li>где реализация «с нуля» разошлась с эталоном из <code>sklearn</code>\nи в чём причина;</li>\n<li>что бы вы улучшили, будь у вас больше времени.</li>\n</ul>\n</div>\n</body>\n</html>\n'}}]);